# Install ImportExcel if not already installed
if (-not (Get-Module -ListAvailable -Name ImportExcel)) {
    Install-Module -Name ImportExcel -Force -Scope CurrentUser
}

# Create the data
$data = @(
    @{Quarter = "Q1"; Value = 100}
    @{Quarter = "Q2"; Value = 120}
    @{Quarter = "Q3"; Value = 134}
)

# Export to Excel
$outputPath = "$PWD\quarterly_data.xlsx"
$data | Export-Excel -Path $outputPath -WorksheetName "Quarterly" -AutoSize

Write-Output "Spreadsheet created: $outputPath"
